const poolBounceWindow = `-- name: PoolBounceWindow :one
SELECT
    CAST(COUNT(*) AS INTEGER) AS sends,
    CAST(COALESCE(SUM(CASE WHEN b.id IS NOT NULL THEN 1 ELSE 0 END), 0) AS INTEGER) AS hard_bounces
FROM (
    SELECT s.id FROM pool_sends s
    WHERE s.mailbox_id = ?1 AND s.created_at >= ?2
      AND s.status <> 'sending' AND COALESCE(s.failure_kind, '') <> 'provider'
    ORDER BY s.created_at DESC
    LIMIT ?3
) w
LEFT JOIN email_bounce b ON b.pool_send_id = w.id AND b.bounce_type = 'Permanent'
`

type PoolBounceWindowParams struct {
	MailboxID  string `json:"mailbox_id"`
	Since      string `json:"since"`
	WindowSize int64  `json:"window_size"`
}

type PoolBounceWindowRow struct {
	Sends       int64 `json:"sends"`
	HardBounces int64 `json:"hard_bounces"`
}

// PoolBounceWindow counts the mailbox's last sends since its health reset
// that reached the provider, and the hard bounces among them.
func (q *Queries) PoolBounceWindow(ctx context.Context, arg PoolBounceWindowParams) (PoolBounceWindowRow, error) {
	row := q.db.QueryRowContext(ctx, poolBounceWindow, arg.MailboxID, arg.Since, arg.WindowSize)
	var i PoolBounceWindowRow
	err := row.Scan(&i.Sends, &i.HardBounces)
	return i, err
}

const poolComplaintWindow = `-- name: PoolComplaintWindow :one
SELECT
    CAST(COUNT(*) AS INTEGER) AS sends,
    CAST(COALESCE(SUM(CASE WHEN c.id IS NOT NULL THEN 1 ELSE 0 END), 0) AS INTEGER) AS complaints
FROM (
    SELECT s.id FROM pool_sends s
    WHERE s.mailbox_id = ?1 AND s.created_at >= ?2
      AND s.status <> 'sending' AND COALESCE(s.failure_kind, '') <> 'provider'
    ORDER BY s.created_at DESC
    LIMIT ?3
) w
LEFT JOIN email_complaint c ON c.pool_send_id = w.id
`

type PoolComplaintWindowParams struct {
	MailboxID  string `json:"mailbox_id"`
	Since      string `json:"since"`
	WindowSize int64  `json:"window_size"`
}

type PoolComplaintWindowRow struct {
	Sends      int64 `json:"sends"`
	Complaints int64 `json:"complaints"`
}

func (q *Queries) PoolComplaintWindow(ctx context.Context, arg PoolComplaintWindowParams) (PoolComplaintWindowRow, error) {
	row := q.db.QueryRowContext(ctx, poolComplaintWindow, arg.MailboxID, arg.Since, arg.WindowSize)
	var i PoolComplaintWindowRow
	err := row.Scan(&i.Sends, &i.Complaints)
	return i, err
}

